WITH fo AS MATERIALIZED (SELECT o.* FROM orders o WHERE lower(o.status)='completed' AND o.created_at::date>=DATE '2024-01-01'), eligible AS (SELECT DISTINCT o.customer_id FROM fo o JOIN order_items oi ON oi.order_id=o.id JOIN products p ON p.id=oi.product_id AND p.active JOIN product_suppliers ps ON ps.product_id=p.id JOIN suppliers s ON s.id=ps.supplier_id AND s.risk_tier>=4 JOIN shipments sh ON sh.order_id=o.id WHERE sh.delivered_at IS NULL OR sh.delivered_at > sh.shipped_at + INTERVAL '10 days'), cap AS (SELECT o.customer_id,count(*) n FROM fo o WHERE EXISTS (SELECT 1 FROM payments p WHERE p.order_id=o.id AND p.status='captured') GROUP BY o.customer_id), rev AS (SELECT o.customer_id,sum((oi.quantity-COALESCE(r.quantity,0))*oi.unit_price) x FROM fo o JOIN order_items oi ON oi.order_id=o.id LEFT JOIN returns r ON r.order_id=oi.order_id AND r.line_no=oi.line_no WHERE EXISTS (SELECT 1 FROM payments p WHERE p.order_id=o.id AND p.status='captured') GROUP BY o.customer_id), promo AS (SELECT o.customer_id,sum(op.discount_amount) x FROM fo o JOIN order_promotions op ON op.order_id=o.id JOIN promotions p ON p.id=op.promotion_id AND p.active GROUP BY o.customer_id), late AS (SELECT o.customer_id,count(*) n FROM fo o JOIN shipments sh ON sh.order_id=o.id WHERE sh.delivered_at IS NULL OR sh.delivered_at > sh.shipped_at + INTERVAL '10 days' GROUP BY o.customer_id), risk AS (SELECT o.customer_id,count(DISTINCT ps.supplier_id) n FROM fo o JOIN order_items oi ON oi.order_id=o.id JOIN product_suppliers ps ON ps.product_id=oi.product_id JOIN suppliers s ON s.id=ps.supplier_id WHERE s.risk_tier>=4 GROUP BY o.customer_id), lasto AS (SELECT customer_id,max(created_at) x FROM fo GROUP BY customer_id) SELECT c.id,c.region,c.segment,COALESCE(cap.n,0),COALESCE(rev.x,0)::numeric(20,2),COALESCE(promo.x,0)::numeric(18,2),COALESCE(late.n,0),COALESCE(risk.n,0),lasto.x FROM customers c JOIN eligible e ON e.customer_id=c.id LEFT JOIN cap ON cap.customer_id=c.id LEFT JOIN rev ON rev.customer_id=c.id LEFT JOIN promo ON promo.customer_id=c.id LEFT JOIN late ON late.customer_id=c.id LEFT JOIN risk ON risk.customer_id=c.id LEFT JOIN lasto ON lasto.customer_id=c.id WHERE c.active;